using System.IO;
using UnityEditor;
using UnityEngine;

namespace CrimsonDraft.Editor
{
    /// <summary>
    /// Import settings for the variants FBX exported by Tools/Blender/soldier_variants.py and the textures
    /// generated by Tools/Blender/soldier_textures.py.
    /// The FBX is only a mesh source (variants are re-bound to each prefab's skeleton by name), so it mirrors
    /// SoldierCharacterRigged.fbx (Generic, no Avatar, file scale) but imports no animations, cameras or
    /// lights, and remaps its materials to the ones the soldier prefabs already use (+ Mat_Gear).
    /// Textures get the same settings as MarineTexture.png (point, no mips, clamp) so the PSX look and the
    /// UV layout match exactly.
    /// </summary>
    public sealed class SoldierVariantsImportSettings : AssetPostprocessor
    {
        public const string VariantsFolder  = "Assets/Art/Models/CharactersFBX/MarineRigged/Variants/";
        public const string TexturesFolder  = VariantsFolder + "Textures/";
        public const string MaterialsFolder = VariantsFolder + "Materials/";
        public const string CamoFolder      = VariantsFolder + "Camo/";
        public const string GearMaterialPath = MaterialsFolder + "Mat_Gear.mat";
        public const string SoldierMaterial1 = "Assets/Art/Animations/Player/Soldier1.mat";
        public const string SoldierMaterial2 = "Assets/Art/Animations/Player/Soldier2.mat";

        private static readonly (string name, string path)[] MaterialRemaps =
        {
            ("Soldier1", SoldierMaterial1),
            ("Soldier2", SoldierMaterial2),
            ("Mat_Gear", GearMaterialPath),
        };

        // Only when the .meta is new (first import / meta deleted): re-exports from Blender keep the saved settings.
        private void OnPreprocessModel()
        {
            if (!this.assetPath.StartsWith(VariantsFolder) || !this.assetPath.EndsWith(".fbx") || !this.assetImporter.importSettingsMissing)
                return;
            Configure((ModelImporter)this.assetImporter);
        }

        private void OnPreprocessTexture()
        {
            if (!this.assetPath.StartsWith(TexturesFolder) || !this.assetImporter.importSettingsMissing)
                return;
            ConfigureTexture((TextureImporter)this.assetImporter);
        }

        [MenuItem("CrimsonDraft/Soldier Appearance/Reapply Variants FBX Import Settings")]
        public static void ReapplyImportSettings()
        {
            if (AssetImporter.GetAtPath(SoldierVariantInstaller.VariantsFbxPath) is ModelImporter importer)
            {
                Configure(importer);
                importer.SaveAndReimport();
            }
        }

        /// <summary>
        /// Creates (or updates the texture of) Mat_Gear and one Mat_Camo_&lt;Name&gt; per Camo_&lt;Name&gt;.png,
        /// all copies of Soldier2.mat (PSX shader settings) with another base map. Never touches Soldier1/2.
        /// </summary>
        [MenuItem("CrimsonDraft/Soldier Appearance/Create Or Update Variant Materials")]
        public static void CreateOrUpdateMaterials()
        {
            var template = AssetDatabase.LoadAssetAtPath<Material>(SoldierMaterial2);
            if (!template)
            {
                Debug.LogError($"[SoldierAppearance] Template material not found: {SoldierMaterial2}");
                return;
            }
            Directory.CreateDirectory(MaterialsFolder);
            Directory.CreateDirectory(CamoFolder);

            foreach (var guid in AssetDatabase.FindAssets("t:Texture2D", new[] { TexturesFolder.TrimEnd('/') }))
            {
                var path = AssetDatabase.GUIDToAssetPath(guid);
                if (AssetImporter.GetAtPath(path) is TextureImporter ti)
                {
                    ConfigureTexture(ti);
                    ti.SaveAndReimport();
                }
                var texture = AssetDatabase.LoadAssetAtPath<Texture2D>(path);
                string file = Path.GetFileNameWithoutExtension(path);
                string materialPath = file == "Gear_Atlas" ? GearMaterialPath
                    : file.StartsWith("Camo_") ? CamoFolder + "Mat_Camo_" + file.Substring("Camo_".Length) + ".mat"
                    : null;
                if (materialPath == null) continue;

                var material = AssetDatabase.LoadAssetAtPath<Material>(materialPath);
                if (!material)
                {
                    material = new Material(template) { name = Path.GetFileNameWithoutExtension(materialPath) };
                    AssetDatabase.CreateAsset(material, materialPath);
                }
                if (material.HasProperty("_BaseMap")) material.SetTexture("_BaseMap", texture);
                if (material.HasProperty("_MainTex")) material.SetTexture("_MainTex", texture);
                EditorUtility.SetDirty(material);
            }
            AssetDatabase.SaveAssets();
            Debug.Log("[SoldierAppearance] Variant materials created/updated.");
        }

        public static void ConfigureTexture(TextureImporter importer)
        {
            var reference = AssetImporter.GetAtPath("Assets/Art/Models/CharactersFBX/Marine Character/MarineTexture.png") as TextureImporter;
            importer.textureType        = TextureImporterType.Default;
            importer.sRGBTexture        = true;
            importer.mipmapEnabled      = false;
            importer.filterMode         = FilterMode.Point;
            importer.wrapMode           = TextureWrapMode.Clamp;
            importer.npotScale          = TextureImporterNPOTScale.None;
            importer.textureCompression = reference ? reference.textureCompression : TextureImporterCompression.Compressed;
            importer.maxTextureSize     = reference ? reference.maxTextureSize : 2048;
        }

        public static void Configure(ModelImporter importer)
        {
            importer.animationType     = ModelImporterAnimationType.Generic;
            importer.avatarSetup       = ModelImporterAvatarSetup.NoAvatar;
            importer.importAnimation   = false;
            importer.importCameras     = false;
            importer.importLights      = false;
            importer.importBlendShapes = true;  // same as the original (the variants have none)
            importer.useFileScale      = true;
            importer.globalScale       = 1f;
            importer.bakeAxisConversion = false;
            importer.isReadable        = false;
            importer.skinWeights       = ModelImporterSkinWeights.Standard; // 4 bones per vertex, like the original
            importer.optimizeBones     = true;

            foreach (var (name, path) in MaterialRemaps)
            {
                var material = AssetDatabase.LoadAssetAtPath<Material>(path);
                if (material)
                    importer.AddRemap(new AssetImporter.SourceAssetIdentifier(typeof(Material), name), material);
            }
        }
    }
}
